const cmdRaw01=document.getElementById("cmd_raw");function addHistory(e){if(Array.isArray(window.cmdLast_01)){let t=window.cmdLast_01.indexOf(e);-1!=t&&window.cmdLast_01.splice(t,1),window.cmdLast_01.push(e)}else window.cmdLast_01=[e]}cmdRaw01.addEventListener("keydown",function(e){"Enter"==e.key&&(e.ctrlKey||e.shiftKey)?this.value+="\r\n":"Enter"==e.key&&(document.getElementById("my_submit").click(),e.preventDefault())}),cmdRaw01.addEventListener("keydown",e=>{if(!Array.isArray(window.cmdLast_01))return;let t=window.cmdLast_01.length;if("ArrowUp"===e.key||"Up"===e.key){if(0==cmdRaw01.value.trim().length)t>0&&(cmdRaw01.value=window.cmdLast_01[t-1]);else{let l=window.cmdLast_01.indexOf(cmdRaw01.value);l>0&&(cmdRaw01.value=window.cmdLast_01[l-1])}e.preventDefault()}else if("ArrowDown"===e.key||"Down"===e.key){if(0==cmdRaw01.value.trim().length)return;let a=window.cmdLast_01.indexOf(cmdRaw01.value);a<t-1&&(cmdRaw01.value=window.cmdLast_01[a+1]),e.preventDefault()}}),document.getElementById("my_submit").addEventListener("click",function(){let e=document.getElementById("cmd_raw"),t=e.value.trim();if(t.length>0){if("clear"==t||"reset"==t||"history"==t||"history -c"==t){addHistory(t),e.value="";let l=document.getElementById("result_all");if("history"==t){if(Array.isArray(window.cmdLast_01))for(let a of window.cmdLast_01)l.value+=`${a}\r
`;l.scrollTop=l.scrollHeight;return}if("history -c"==t){window.cmdLast_01=[];return}l.value="";return}let r=Base64.encode(t),d="?cmd="+r;null!=window.pathDir_01&&(d+="&dir="+Base64.encode(window.pathDir_01)),fetch(d).then(e=>e.json()).then(t=>{let l=document.getElementById("result_all");0==t.code?(l.value+=Base64.decode(t.cmd)+"\r\n"+Base64.decode(t.result)+"\r\n",window.pathDir_01=t.dir):l.value+="不支持此命令: "+e.value+"\r\n",addHistory(e.value),e.value="",l.scrollTop=l.scrollHeight}).catch(e=>{location.href="/ala/quit.html"})}else alert("命令为空")});